INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1425524-geol202', 'stk-ziyad_al-amoud', 'GEOL 202', 'srcU', '{"html": "حضرت اول كلاس للكورس …<br><br>المادة شكلها ممتعة وسهلة … ما أتوقع انها راح تاخذ منك وقت بالمذاكرة والشغل …<br><br>الدكتور حبيب ويحببك بالمادة … تقدر تسأله بأي شيء وهو يشجعك بانك تسأله …<br><br>المادة أفرج ويمكن تكون ميزة أو سلبية<br><br>سلبيات المادة :1-المادة مالها كتاب أو سورس تذاكر منه … السلايدات عامة جدا ولازم تكتب نوت ولو غبت كلاس راح عليك شيء كثير إلا لو الطلاب متعاونين معك<br><br>2-الكلاس وورك عليه درجات كثيرة (51%!!)شاملة الأتيندنس والكويزات والكيس ستديز (4 ريسيرتش لكنه الدكتور يقول إن كلها قصيرة ومتعلقة بتخصصك)<br><br>3- السكشن يوم أحضر ما كان فيه الا اثنين معي بس 😛 لكن على كلام الدكتور فيه عشرة مسجلين فيه<br><br>عموما السيلابس موجود بالمرفقات لو ودك تشوفه<br><br>وإذا عندك أي سؤال ثاني تفضل 🤠<br><br>​<span data-fid=\"stk-f1425524-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1425524-0": {"name": "Course-outlines-151-1 .zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/geol202/169332/3", "user": "Ziyad_Al-Amoud", "ts": 1440445665000, "tid": 169332, "pn": 3}}', 1440445665000, 1794826860, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
